#include <vector>
#include <sstream>
#include <algorithm>
using namespace std;
class AnyListGrader {
public:
 static void setup(AnyList& l,vector<int> values){Node* tail=nullptr;for(int v:values){Node* n=new Node(v,nullptr);if(tail)tail->setNext(n);else l.first=n;tail=n;}l.count=values.size();}
 static vector<Node*> nodes(AnyList& l){vector<Node*> n;Node* p=l.first;while(p&&n.size()<50&&find(n.begin(),n.end(),p)==n.end()){n.push_back(p);p=p->getNext();}return n;}
 static string check(AnyList& l,const vector<int>& expected,const vector<Node*>& oldNodes,int kind){
  auto now=nodes(l);bool valid=l.count==(int)expected.size()&&now.size()==expected.size();
  if(now.empty())valid=valid&&!l.first;else valid=valid&&l.first==now.front()&&!now.back()->getNext();
  for(size_t i=0;i<now.size();++i){valid=valid&&i<expected.size()&&now[i]->getData()==expected[i];valid=valid&&now[i]->getNext()==(i+1<now.size()?now[i+1]:nullptr);}
  if(kind==2)valid=valid&&now==oldNodes;
  vector<Node*> retained;for(auto n:now)if(find(oldNodes.begin(),oldNodes.end(),n)!=oldNodes.end())retained.push_back(n);
  if(kind==1)valid=valid&&retained==oldNodes;
  if(kind==0){vector<Node*> oldRetained;for(auto n:oldNodes)if(find(now.begin(),now.end(),n)!=now.end())oldRetained.push_back(n);valid=valid&&retained.size()==now.size()&&retained==oldRetained;}
  ostringstream out;out<<(valid?"PASS":"FAIL")<<"|[";for(size_t i=0;i<now.size();++i){if(i)out<<", ";out<<now[i]->getData();}out<<"]";if(!valid)out<<" (check values, forward links, count, and node identity)";
  l.first=nullptr;l.count=0;return out.str();
 }
};

int main(){{AnyList l,other;AnyListGrader::setup(l,{10});AnyListGrader::setup(other,{});auto old=AnyListGrader::nodes(l);auto oldOther=AnyListGrader::nodes(other);l.deleteFirst();auto result=AnyListGrader::check(l,{},old,0);cout<<"TEST1|"<<result<<"\n";}
{AnyList l,other;AnyListGrader::setup(l,{10,20});AnyListGrader::setup(other,{});auto old=AnyListGrader::nodes(l);auto oldOther=AnyListGrader::nodes(other);l.deleteFirst();auto result=AnyListGrader::check(l,{20},old,0);cout<<"TEST2|"<<result<<"\n";}
