{AnyList l,other;AnyListGrader::setup(l,{6,2,5,3,9});AnyListGrader::setup(other,{});auto old=AnyListGrader::nodes(l);auto oldOther=AnyListGrader::nodes(other);l.deleteFirst();auto result=AnyListGrader::check(l,{2,5,3,9},old,0);cout<<"TEST4|"<<result<<"\n";}
