 static vector<Node*> nodes(AnyList& l){vector<Node*> n;Node* p=l.first;while(p&&n.size()<50&&find(n.begin(),n.end(),p)==n.end()){n.push_back(p);p=p->getNext();}return n;}
 static string check(AnyList& l,const vector<int>& expected,const vector<Node*>& oldNodes,int kind){
  auto now=nodes(l);bool valid=l.count==(int)expected.size()&&now.size()==expected.size();
