  if(kind==0){vector<Node*> oldRetained;for(auto n:oldNodes)if(find(now.begin(),now.end(),n)!=now.end())oldRetained.push_back(n);valid=valid&&retained.size()==now.size()&&retained==oldRetained;}
  ostringstream out;out<<(valid?"PASS":"FAIL")<<"|[";for(size_t i=0;i<now.size();++i){if(i)out<<", ";out<<now[i]->getData();}out<<"]";if(!valid)out<<" (check values, forward links, count, and node identity)";
  l.first=nullptr;l.count=0;return out.str();
 }
};

